    ('20260929_2_regularize_extended_window', 'column tenants.regularize_extended_until', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='tenants' AND column_name='regularize_extended_until')),
    ('20260929_2_regularize_extended_window', 'function enforce_regularize_request_window() [latest body]', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='enforce_regularize_request_window' AND position('SELECT COALESCE(regularize_window_days, 3), regularize_extended_from, regularize_extended_until' in p.prosrc) > 0)),
    ('20260929_3_pms_cycle_review_auth_first', 'function pms_submit_cycle_assessment() [latest body]', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='pms_submit_cycle_assessment' AND position('SELECT * INTO r FROM pms_cycle_reviews WHERE id = p_review AND tenant_id = a.tenant_id FOR UPDATE;' in p.prosrc) > 0)),
    ('20260929_3_raniwala_celebrations_team_today', 'function list_upcoming_celebrations() [latest body]', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='list_upcoming_celebrations' AND position('WHEN (e.event_date + make_interval(years => EXTRACT(YEAR FROM v_today)::int - EXTRACT(YEAR FROM e.event_date)::int))::date >= v_today' in p.prosrc) > 0)),
    ('20260929_4_pms_edit_goal_kpi', 'function pms_card_issues() [latest body]', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='pms_card_issues' AND position('IF NOT EXISTS (SELECT 1 FROM pms_kpis WHERE tenant_id = p_tenant AND fy = p_fy AND owner_type = p_type AND owner_id = p_owner) THEN' in p.prosrc) > 0)),
    ('20260929_4_pms_edit_goal_kpi', 'function pms_update_goal() [latest body]', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='pms_update_goal' AND position('IF (v_target IS DISTINCT FROM g.annual_target OR v_unit IS DISTINCT FROM g.unit) AND pms_goal_protected(g.parent_id) THEN' in p.prosrc) > 0)),
    ('20260929_4_pms_edit_goal_kpi', 'function pms_update_kpi() [latest body]', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='pms_update_kpi' AND position('IF v_sub IS NULL OR v_app IS NULL OR NOT pms_active_member(a.tenant_id, v_sub) OR NOT pms_active_member(a.tenant_id, v_app) THEN' in p.prosrc) > 0)),
    ('20260929_4_raniwala_regularize_own_manager_plus_hr', 'function enforce_regularize_request_approval_tier() [latest body]', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='enforce_regularize_request_approval_tier' AND position('SELECT regularize_auto_approval_enabled, regularize_auto_approval_limit, company_name' in p.prosrc) > 0)),
    ('20260929_4_raniwala_regularize_own_manager_plus_hr', 'function trg_team_only_request_notifications() [latest body]', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='trg_team_only_request_notifications' AND position('(SELECT COALESCE(a.manager_id, a.hod_id) FROM profiles a WHERE a.id = NEW.actor_id) THEN' in p.prosrc) > 0))
),
per_file AS (
  SELECT migration,
         count(*)                                  AS objects,
         count(*) FILTER (WHERE ok)                AS found,
         string_agg(object, '; ') FILTER (WHERE NOT ok) AS missing
  FROM probes GROUP BY migration
)
SELECT migration,
       CASE WHEN found = objects THEN 'applied'
            WHEN found = 0       THEN 'PENDING'
            ELSE 'PARTIAL' END AS verdict,
       found || '/' || objects AS found_of,
       missing
FROM per_file
WHERE found < objects           -- remove this line to see every file
UNION ALL
SELECT m, 'no schema objects - check data', '-', NULL
FROM unnest(ARRAY['20260607_payroll_compliance_group', '20260610_fix_payroll_country_group', '20260726_actor_fk_set_null', '20260726_departments_superadmin_bypass', '20260726_tenant_delete_fk_fix', '20260806_announcements_drop_legacy_message', '20260806_audit_log_self_insert', '20260813_8_keka_leave_categories', '20260813_11_announcements_rls_lockdown', '20260815_3_onboarding_offboarding_features', '20260815_6_assets_projects_features', '20260820_profiles_select_role_check', '20260820_3_otp_table_lockdown', '20260820_4_punches_select_role_check', '20260820_9_recruitment_checklist_seed', '20260823_4_hierarchy_rbac_backfill', '20260826_2_org_hierarchy_feature', '20260901_1_hr_current_password_read', '20260903_4_auto_approval_default_off', '20260915_2_backfill_late_status_recent', '20260917_2_raniwala_timing_attendance_policy', '20260917_3_raniwala_realtime_comp_off', '20260917_5_raniwala_jewellers_holidays', '20260917_6_raniwala_employee_master_caps', '20260917_7_raniwala_department_division_case_cleanup', '20260917_8_raniwala_outlet_division_backfill', '20260917_9_raniwala_office_division_backfill', '20260918_5_raniwala_b2b_sales_rename', '20260918_6_raniwala_retire_worklocation_outlet', '20260921_1_raniwala_tenant_weekly_off_sunday', '20260921_3_raniwala_hide_refer_interviews', '20260922_1_raniwala_enable_live_tracking', '20260923_4_profiles_select_lockdown', '20260924_1_raniwala_leave_types_policy', '20260924_2_raniwala_leave_balance_dob_import', '20260924_3_raniwala_dedupe_misfortune_leave_type', '20260925_1_raniwala_himanshi_leave_balance_fix', '20260925_2_leave_balances_detail_security_invoker', '20260925_4_raniwala_mispunch_backfill_sept', '20260925_5_attendance_status_check_widen', '20260926_4_raniwala_manager_portal_scope', '20260926_7_raniwala_org_structure_from_hod_sheet', '20260926_8_raniwala_merge_duplicate_departments', '20260926_13_fix_new_user_trigger_search_path', '20260926_13_raniwala_link_management_owners', '20260928_9_essl_hr_only']::text[]) AS m
